<?php session_start();require 'conectare.php';$id=filter_input(INPUT_GET,'id_autor',FILTER_VALIDATE_INT)?:0;$s=$pdo->prepare('SELECT nume_autor FROM autori WHERE id_autor=?');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Autor inexistent.');}$s=$pdo->prepare('SELECT id_carte,titlu,pret FROM carti WHERE id_autor=? ORDER BY titlu');$s->execute([$id]);$books=$s->fetchAll();include 'page_top.php';include 'meniu.php';?><td valign="top"><h1><?=h($a['nume_autor'])?></h1><?php foreach($books as $b):?><p><a href="carte.php?id_carte=<?=(int)$b['id_carte']?>"><b><?=h($b['titlu'])?></b></a> — <?=number_format((float)$b['pret'],2,',','.')?> lei</p><?php endforeach;?></td><?php include 'page_bottom.php';?>
